-- Audit log: who changed what, and when (V3, issue #223)
-- Target: Aurora PostgreSQL compatible SQL (PostgreSQL 15+), on top of 002-005.
--
-- The API writes one row per inserted / updated / deleted row, in the same transaction as
-- the change (backend/app/v2/audit.py). Append-only: nothing updates or deletes rows here.

BEGIN;

CREATE TABLE "audit_log" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "occurred_at" timestamptz NOT NULL DEFAULT (now()),
  "actor_id" uuid,
  "actor_roles" varchar(100) NOT NULL DEFAULT '',
  "request" varchar(300),
  "action" varchar(10) NOT NULL,
  "entity" varchar(50) NOT NULL,
  "entity_id" varchar(100) NOT NULL,
  "changes" jsonb,
  CONSTRAINT "chk_audit_log_action" CHECK ("action" IN ('insert', 'update', 'delete'))
);

CREATE INDEX ON "audit_log" ("entity", "entity_id");
CREATE INDEX ON "audit_log" ("actor_id");
CREATE INDEX ON "audit_log" ("occurred_at");

COMMIT;
